  box.innerHTML=`<div class="balance-box"><div><small>PRECIO DE VENTA</small><strong>${money(Math.round(Number(p.price||0)*100))}</strong></div><div>${publication(p)}</div></div><p>${esc(p.description||'Sin descripción adicional.')}</p><div class="hint neutral">Tu acceso permite consultar esta ficha. Un administrador puede cambiar precios, fotos y publicación.</div>`;$('product-form').replaceWith(box);
